define(['jquery','core/notification','core/ajax'],function($,Notification,Ajax){'use strict';class LiveClassroom{constructor(config){this.config=config;this.localStream=null;this.screenStream=null;this.isMicMuted=false;this.isCamOff=false;this.isScreenSharing=false;this.tabSwitchCount=0;this.elapsedSeconds=0;this.timerInterval=null;this.room=null;this.bindEvents();}bindEvents(){const self=this;$('#btn-join-liveclass').on('click',function(e){e.preventDefault();self.startClassroom();});if(this.config.warnTabSwitch){document.addEventListener('visibilitychange',()=>{if(document.hidden){self.handleTabHidden();}else{self.handleTabRestored();}});window.addEventListener('blur',()=>{self.logEvent('focus_lost','Window lost focus');});}}startClassroom(){const self=this;const stage=$('#liveclass-stage');stage.html(`<div class="liveclass-active-workspace w-100 h-100 d-flex flex-column" style="min-height:580px;"><div class="liveclass-top-bar d-flex justify-content-between align-items-center p-2 bg-dark text-white border-bottom border-secondary"><div class="d-flex align-items-center gap-2"><span class="badge bg-danger rounded-pill px-3 py-2 animate-pulse"><i class="fa fa-circle"></i> مباشر</span><span class="fw-bold ms-2">${self.config.roomName}</span></div><div class="d-flex align-items-center gap-3"><span class="badge bg-secondary p-2" id="live-timer"><i class="fa fa-clock-o"></i> 00:00:00</span><span class="badge bg-info p-2" id="attendance-status-badge"><i class="fa fa-percent"></i> 0% الحضور</span></div></div><div class="liveclass-media-viewport flex-grow-1 d-flex position-relative bg-black"><div id="video-grid" class="w-100 h-100 d-flex flex-wrap justify-content-center align-items-center p-2 gap-2 position-relative"><div class="video-card local-video-card position-relative bg-dark rounded overflow-hidden shadow" style="width:100%;max-width:800px;height:450px;"><video id="local-video" class="w-100 h-100" style="object-fit:cover;" autoplay playsinline muted></video><div class="position-absolute bottom-0 start-0 p-2 bg-dark bg-opacity-75 text-white m-2 rounded small"><i class="fa fa-user"></i> ${self.config.displayName} ${self.config.isModerator?'(المدرب)':''}</div></div></div><div id="presence-alert" class="position-absolute top-0 start-50 translate-middle-x mt-3 alert alert-warning shadow d-none" style="z-index:1050;"><i class="fa fa-exclamation-triangle"></i> <strong>تنبيه:</strong> لقد قمت بمغادرة نافذة الحصة! يتم تسجيل هذا السلوك آلياً في سجل التواجد.</div></div><div class="liveclass-toolbar bg-dark p-3 d-flex justify-content-center align-items-center gap-3 border-top border-secondary"><button id="btn-toggle-mic" class="btn btn-outline-light rounded-circle p-3" title="كتم/تشغيل المايك"><i class="fa fa-microphone fa-lg"></i></button><button id="btn-toggle-cam" class="btn btn-outline-light rounded-circle p-3" title="تشغيل/إيقاف الكاميرا"><i class="fa fa-video-camera fa-lg"></i></button><button id="btn-toggle-screen" class="btn btn-outline-light rounded-circle p-3" title="مشاركة الشاشة"><i class="fa fa-desktop fa-lg"></i></button><button id="btn-raise-hand" class="btn btn-outline-warning rounded-circle p-3" title="رفع اليد"><i class="fa fa-hand-paper-o fa-lg"></i></button><button id="btn-fullscreen" class="btn btn-outline-light rounded-circle p-3" title="ملء الشاشة"><i class="fa fa-arrows-alt fa-lg"></i></button><button id="btn-leave" class="btn btn-danger rounded-pill px-4 ms-3" title="مغادرة الحصة"><i class="fa fa-phone"></i> مغادرة</button></div></div>`);self.initMediaStream();self.startAttendanceTimer();self.bindToolbarControls();}async initMediaStream(){try{this.localStream=await navigator.mediaDevices.getUserMedia({audio:true,video:{width:1280,height:720}});const videoEl=document.getElementById('local-video');if(videoEl){videoEl.srcObject=this.localStream;}}catch(err){console.warn('[LiveClass] Camera/Mic access denied or unavailable:',err);try{this.localStream=await navigator.mediaDevices.getUserMedia({audio:true});}catch(e){console.error('[LiveClass] Complete media permission failure:',e);}}}bindToolbarControls(){const self=this;$('#btn-toggle-mic').on('click',function(){if(self.localStream&&self.localStream.getAudioTracks().length>0){self.isMicMuted=!self.isMicMuted;self.localStream.getAudioTracks()[0].enabled=!self.isMicMuted;$(this).toggleClass('btn-outline-light btn-danger');$(this).find('i').toggleClass('fa-microphone fa-microphone-slash');}});$('#btn-toggle-cam').on('click',function(){if(self.localStream&&self.localStream.getVideoTracks().length>0){self.isCamOff=!self.isCamOff;self.localStream.getVideoTracks()[0].enabled=!self.isCamOff;$(this).toggleClass('btn-outline-light btn-danger');$(this).find('i').toggleClass('fa-video-camera fa-eye-slash');}});$('#btn-toggle-screen').on('click',async function(){if(!self.isScreenSharing){try{self.screenStream=await navigator.mediaDevices.getDisplayMedia({video:true});const videoEl=document.getElementById('local-video');if(videoEl){videoEl.srcObject=self.screenStream;}self.isScreenSharing=true;$(this).addClass('btn-primary').removeClass('btn-outline-light');self.screenStream.getVideoTracks()[0].onended=()=>{self.stopScreenShare();};}catch(err){console.warn('[LiveClass] Screen share cancelled:',err);}}else{self.stopScreenShare();}});$('#btn-raise-hand').on('click',function(){$(this).toggleClass('btn-outline-warning btn-warning text-dark');self.logEvent('raise_hand','Student raised hand');});$('#btn-fullscreen').on('click',function(){const el=document.getElementById('liveclass-stage');if(!document.fullscreenElement){el.requestFullscreen().catch(err=>console.error(err));}else{document.exitFullscreen();}});$('#btn-leave').on('click',function(){if(confirm('هل أنت متأكد من مغادرة الحصة الافتراضية؟')){self.leaveClassroom();}});}stopScreenShare(){if(this.screenStream){this.screenStream.getTracks().forEach(t=>t.stop());this.screenStream=null;}this.isScreenSharing=false;$('#btn-toggle-screen').removeClass('btn-primary').addClass('btn-outline-light');const videoEl=document.getElementById('local-video');if(videoEl&&this.localStream){videoEl.srcObject=this.localStream;}}startAttendanceTimer(){const self=this;this.timerInterval=setInterval(()=>{self.elapsedSeconds++;const hrs=String(Math.floor(self.elapsedSeconds/3600)).padStart(2,'0');const mins=String(Math.floor((self.elapsedSeconds%3600)/60)).padStart(2,'0');const secs=String(self.elapsedSeconds%60).padStart(2,'0');$('#live-timer').html(`<i class="fa fa-clock-o"></i> ${hrs}:${mins}:${secs}`);const plannedSeconds=Math.max(60,(self.config.endTime-self.config.startTime)||3600);const currentPct=Math.min(100,Math.round((self.elapsedSeconds/plannedSeconds)*100));$('#attendance-progress').css('width',currentPct+'%').text(currentPct+'%');$('#attendance-status-badge').html(`<i class="fa fa-percent"></i> ${currentPct}% الحضور`);if(currentPct>=self.config.minAttendancePct){$('#attendance-status-badge').removeClass('bg-info').addClass('bg-success');$('#attendance-progress').removeClass('bg-info').addClass('bg-success');}},1000);}handleTabHidden(){this.tabSwitchCount++;$('#presence-alert').removeClass('d-none');this.logEvent('tab_hidden',`Tab hidden count: ${this.tabSwitchCount}`);}handleTabRestored(){setTimeout(()=>{$('#presence-alert').addClass('d-none');},3000);this.logEvent('tab_restored','Student returned to classroom window');}logEvent(eventType,details){$.ajax({url:M.cfg.wwwroot+'/mod/liveclass/log_event.php',type:'POST',data:{sesskey:this.config.sesskey,cmid:this.config.cmid,sessionid:this.config.sessionId,eventtype:eventType,details:details},dataType:'json'});}leaveClassroom(){if(this.timerInterval)clearInterval(this.timerInterval);if(this.localStream)this.localStream.getTracks().forEach(t=>t.stop());if(this.screenStream)this.screenStream.getTracks().forEach(t=>t.stop());window.location.reload();}}return{init:function(config){return new LiveClassroom(config);}};});

